// Initialize check context
return [{
  json: {
    targetUrl: 'https://demo.realworld.io',
    targetName: 'Conduit RealWorld Demo',
    checkTime: new Date().toISOString(),
    maxRetries: 3,
    currentRetry: 0
  }
}];

// Evaluate the ping response and record timing
const pingResponse = $input.first().json;
const initData = $('Initialize Check').first().json;

// Calculate response time (approximate)
const checkTime = new Date(initData.checkTime);
const responseTime = Date.now() - checkTime.getTime();

const statusCode = pingResponse.statusCode || 0;
const isUp = statusCode === 200;
const isWarning = statusCode >= 300 && statusCode < 400;
const isDown = !isUp && !isWarning;

return [{
  json: {
    ...initData,
    statusCode: statusCode,
    responseTimeMs: responseTime,
    isUp: isUp,
    isDown: isDown,
    isWarning: isWarning,
    status: isUp ? 'UP' : (isWarning ? 'REDIRECT' : 'DOWN'),
    errorMessage: pingResponse.error || null
  }
}];

// App is healthy — log silently (optional: post to Discord periodically)
const data = $input.first().json;

console.log(`[UPTIME] ${data.targetName} is UP | Status: ${data.statusCode} | Response: ${data.responseTimeMs}ms | ${data.checkTime}`);

// Check if response time is slow (> 3 seconds) — warn even if up
const isSlowResponse = data.responseTimeMs > 3000;

return [{
  json: {
    ...data,
    action: isSlowResponse ? 'SLOW_WARNING' : 'OK',
    message: isSlowResponse
      ? `⚠️ App responded slowly (${data.responseTimeMs}ms > 3000ms threshold)`
      : `✅ App is healthy`
  }
}];

// App is DOWN — retry up to 2 more times before alerting
// In n8n, we trigger a wait then re-ping via a loop simulation using a counter
const data = $input.first().json;
console.error(`[UPTIME ALERT] ${data.targetName} is DOWN | Status: ${data.statusCode} | ${data.checkTime}`);

return [{ json: data }];

// After retry, determine if still down
const retryResponse = $input.first().json;
const originalData = $('Retry Delay (Simulate Wait)').first().json;

const statusCode = retryResponse.statusCode || 0;
const isStillDown = statusCode !== 200;

return [{
  json: {
    ...originalData,
    retryStatusCode: statusCode,
    isStillDown: isStillDown,
    alertType: isStillDown ? 'CONFIRMED_DOWN' : 'RECOVERED'
  }
}];

// Format DOWN alert for Discord
const data = $input.first().json;

const statusEmoji = data.alertType === 'CONFIRMED_DOWN' ? '🔴' : '🟢';
const statusText = data.alertType === 'CONFIRMED_DOWN' ? 'CONFIRMED DOWN' : 'RECOVERED';

const embed = {
  embeds: [
    {
      title: `${statusEmoji} UPTIME ALERT: ${data.targetName} is ${statusText}`,
      description: [
        `**URL:** ${data.targetUrl}`,
        `**Initial Status Code:** \`${data.statusCode}\``,
        `**Retry Status Code:** \`${data.retryStatusCode}\``,
        `**Response Time:** ${data.responseTimeMs}ms`,
        `**Detected At:** ${new Date(data.checkTime).toUTCString()}`,
        `**Error:** ${data.errorMessage || 'No specific error captured'}`,
        '',
        data.alertType === 'CONFIRMED_DOWN'
          ? '⚠️ *The application failed TWO consecutive health checks. Immediate investigation required!*'
          : '✅ *The application recovered after the retry check. No further action needed.*'
      ].join('\n'),
      color: data.alertType === 'CONFIRMED_DOWN' ? 15548997 : 5832543,
      footer: {
        text: `n8n Uptime Monitor · Checks every 5 minutes`
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{ json: embed }];

// Format slow response warning for Discord
const data = $input.first().json;

const embed = {
  embeds: [
    {
      title: `🐌 SLOW RESPONSE WARNING: ${data.targetName}`,
      description: [
        `**URL:** ${data.targetUrl}`,
        `**HTTP Status:** \`${data.statusCode}\` (OK but slow)`,
        `**Response Time:** **${data.responseTimeMs}ms** (threshold: 3000ms)`,
        `**Detected At:** ${new Date(data.checkTime).toUTCString()}`,
        '',
        '⚠️ *The app is up but responding slowly. Check server resources or network latency.*'
      ].join('\n'),
      color: 16744272,
      footer: {
        text: `n8n Uptime Monitor · Slow Response Alert`
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{ json: embed }];

// Build daily summary digest
const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);

const embed = {
  embeds: [
    {
      title: '📊 Daily Uptime Summary — Conduit RealWorld Demo',
      description: [
        `**Date:** ${yesterday.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}`,
        '',
        '**Summary**',
        '• Monitoring ran every 5 minutes (288 checks/day)',
        '• ✅ Check n8n execution history for full uptime data',
        '• 🔗 Target: https://demo.realworld.io',
        '',
        '**How to view full history:**',
        'Go to n8n → Executions → Filter by workflow "Bonus_UptimeMonitor_Srimanth"',
        '',
        '*This is your automated daily uptime summary. Alerts above indicate any outages detected.*'
      ].join('\n'),
      color: 5814783,
      footer: {
        text: 'n8n Uptime Monitor · Daily Summary'
      },
      timestamp: now.toISOString()
    }
  ]
};

return [{ json: embed }];

const error = $input.first().json;
const embed = {
  embeds: [{
    title: '🚨 Uptime Monitor Workflow Error',
    description: [
      `**Node:** \`${error.node?.name || 'Unknown'}\``,
      `**Error:** ${error.error?.message || 'Unknown error'}`,
      `**Time:** ${new Date().toISOString()}`,
      '',
      '*The uptime monitor encountered an internal error and could not complete a check.*'
    ].join('\n'),
    color: 15548997,
    footer: { text: 'n8n Error Handler' }
  }]
};
return [{ json: embed }];
